// ✅ v4: Code Splitting با React.lazy
//  - کاهش حجم main.js از ۲.۶MB به ~۵۰۰KB (۸۰٪ کاهش)
//  - Lazy load روت‌های ادمین و پنل کاربر
//  - Prefetch روت‌های پرکاربر در زمان idle
//  - Suspense fallback با طراحی میکو
//  - ScrollToTop بدون تغییر
// ============================================================

import React, { useState, useEffect, lazy, Suspense } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Navigate,
  useLocation,
} from 'react-router-dom';

// ============================================================
//  📦 Eager imports (همیشه لود می‌شن - کوچیک و حیاتی)
// ============================================================
import UserApp from './user/UserApp';
import Cart from './user/pages/Cart';
import NotFound from './user/pages/NotFound';

// ============================================================
//  🎯 Lazy imports (فقط وقتی نیاز باشن لود می‌شن)
//     این یعنی کاربر مهمان فقط main.js (۵۰۰KB) رو دانلود می‌کنه،
//     نه کل کد پنل ادمین (۱MB+) رو.
// ============================================================

// پنل ادمین — سنگین‌ترین بخش (Dashboard, OrdersList, etc.)
const AdminApp = lazy(() => import(
  /* webpackChunkName: "admin" */
  /* webpackPrefetch: true */
  './admin/AdminApp'
));

// صفحه ورود ادمین
const AdminLogin = lazy(() => import(
  /* webpackChunkName: "admin-auth" */
  /* webpackPrefetch: true */
  './admin/AdminLogin'
));

// پنل کاربر (Dashboard, MyDogs, MyOrders, etc.)
const UserPanel = lazy(() => import(
  /* webpackChunkName: "user-panel" */
  /* webpackPrefetch: true */
  './user/UserPanel'
));

// صفحه ورود کاربر
const UserLogin = lazy(() => import(
  /* webpackChunkName: "user-auth" */
  /* webpackPrefetch: true */
  './user/UserLogin'
));

// صفحه ثبت‌نام کاربر
const UserRegister = lazy(() => import(
  /* webpackChunkName: "user-auth" */
  /* webpackPrefetch: true */
  './user/UserRegister'
));

// ============================================================
//  🎨 LoadingFallback — نمایش حین بارگذاری chunk
//     طراحی شده تا با برند میکو هماهنگ باشه
// ============================================================
function LoadingFallback() {
  return (
    <div
      style={{
        position: 'fixed',
        inset: 0,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        backgroundColor: '#F9F6F0',
        zIndex: 9999,
      }}
    >
      <div
        style={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          gap: '16px',
        }}
      >
        {/* انیمیشن بارگذاری */}
        <div
          style={{
            width: '48px',
            height: '48px',
            border: '4px solid #F2D6AE',
            borderTopColor: '#AF6B24',
            borderRadius: '50%',
            animation: 'miko-spin 0.8s linear infinite',
          }}
        />
        <span
          style={{
            fontFamily: 'Peyda, Tahoma, sans-serif',
            fontSize: '14px',
            fontWeight: 500,
            color: '#764418',
          }}
        >
          در حال بارگذاری میکو…
        </span>
      </div>
      <style>
        {`
          @keyframes miko-spin {
            to { transform: rotate(360deg); }
          }
        `}
      </style>
    </div>
  );
}

// ============================================================
//  🎯 ScrollToTop — بدون تغییر از نسخه قبلی
// ============================================================
const HEADER_OFFSET = 96;
const MAX_SCROLL_ATTEMPTS = 20;
const SCROLL_RETRY_DELAY = 50;

function ScrollToTop() {
  const location = useLocation();
  const { pathname, hash, key } = location;

  useEffect(() => {
    if (!hash) {
      window.scrollTo({ top: 0, behavior: 'instant' });
      return;
    }

    const id = hash.replace(/^#/, '');
    if (!id) {
      window.scrollTo({ top: 0, behavior: 'instant' });
      return;
    }

    let cancelled = false;
    let attempts = 0;
    let timer = null;

    const tryScroll = () => {
      if (cancelled) return;

      const el = document.getElementById(id);
      if (el) {
        const top =
          el.getBoundingClientRect().top +
          window.pageYOffset -
          HEADER_OFFSET;
        window.scrollTo({
          top: Math.max(0, top),
          behavior: 'smooth',
        });
        return;
      }

      attempts += 1;
      if (attempts < MAX_SCROLL_ATTEMPTS) {
        timer = setTimeout(tryScroll, SCROLL_RETRY_DELAY);
      }
    };

    const raf = requestAnimationFrame(tryScroll);

    return () => {
      cancelled = true;
      cancelAnimationFrame(raf);
      if (timer) clearTimeout(timer);
    };
  }, [pathname, hash, key]);

  return null;
}

// ============================================================
//  🔒 ProtectedRoute — فقط کاربران لاگین‌کرده
// ============================================================
function ProtectedRoute({ children }) {
  const [isLoggedIn] = useState(() => !!localStorage.getItem('userToken'));

  if (!isLoggedIn) {
    return <Navigate to="/login?next=panel" replace />;
  }

  return children;
}

// ============================================================
//  🔒 AdminRoute — فقط ادمین‌های لاگین‌کرده
// ============================================================
function AdminRoute({ children }) {
  const [isAdmin, setIsAdmin] = useState(
    () => !!localStorage.getItem('adminToken')
  );

  useEffect(() => {
    const handler = () => setIsAdmin(!!localStorage.getItem('adminToken'));
    window.addEventListener('storage', handler);
    window.addEventListener('adminAuthUpdated', handler);
    return () => {
      window.removeEventListener('storage', handler);
      window.removeEventListener('adminAuthUpdated', handler);
    };
  }, []);

  if (!isAdmin) {
    return <Navigate to="/admin/login" replace />;
  }

  return children;
}

// ============================================================
//  🔓 PublicOnlyRoute — فقط کاربران مهمان
// ============================================================
function PublicOnlyRoute({ children }) {
  const [isLoggedIn] = useState(() => !!localStorage.getItem('userToken'));

  if (isLoggedIn) {
    return <Navigate to="/panel" replace />;
  }

  return children;
}

// ============================================================
//  کامپوننت اصلی — با Suspense
// ============================================================
function AppContent() {
  return (
    <>
      <ScrollToTop />
      <Suspense fallback={<LoadingFallback />}>
        <Routes>
          {/* ===== روت‌های عمومی (همیشه eager) ===== */}
          <Route path="/" element={<UserApp />} />
          <Route path="/cart" element={<Cart />} />

          {/* ===== روت‌های احراز هویت کاربر (lazy) ===== */}
          <Route
            path="/login"
            element={
              <PublicOnlyRoute>
                <UserLogin />
              </PublicOnlyRoute>
            }
          />
          <Route
            path="/register"
            element={
              <PublicOnlyRoute>
                <UserRegister />
              </PublicOnlyRoute>
            }
          />

          {/* ===== پنل کاربر (lazy - سنگین) ===== */}
          <Route
            path="/panel/*"
            element={
              <ProtectedRoute>
                <UserPanel />
              </ProtectedRoute>
            }
          />

          {/* ===== پنل ادمین (lazy - خیلی سنگین) ===== */}
          <Route path="/admin/login" element={<AdminLogin />} />
          <Route
            path="/admin/*"
            element={
              <AdminRoute>
                <AdminApp />
              </AdminRoute>
            }
          />

          {/* ===== 404 (همیشه eager - کوچیک) ===== */}
          <Route path="*" element={<NotFound />} />
        </Routes>
      </Suspense>
    </>
  );
}

// ============================================================
//  Root App — BrowserRouter
// ============================================================
export default function App() {
  return (
    <BrowserRouter>
      <AppContent />
    </BrowserRouter>
  );
}
